function art(kind='urban',hero=false){if(!hero)return photo(kind);const color=hero?'#72c8e3':'#577e91',light=hero?'#b0e6f5':'#b2ceda',bg=hero?'none':kind==='solar'?'#e3eef3':kind==='agro'?'#e7efeb':'#e6eef3';let objects='';if(kind==='urban'){objects=`<path d="M95 250V90l87-37 76 38v159M182 53v197M258 250V130l80-35 75 35v120M338 95v155M95 90l87 37 76-36M258 130l80 35 75-35"/><path d="M115 112v115m24-125v125m24-135v135m43-86v86m24-98v98m49-74v57m25-68v68m57-55v55m25-67v67" opacity=".5"/><path d="m65 250 178 80 205-80M65 250l28-13m355 13-35-15"/>`;}else if(kind==='solar'){objects=`<circle cx="388" cy="68" r="31"/><path d="M388 17V8m0 120v-9M337 68h-10m121 0h-10M352 32l-8-8m80 80 8 8m-8-80 8-8M190 145l128-29 59 82-128 30zm-18 15-128 29 59 82 128-29zM254 130l59 82m-85-76 59 82m-84-76 58 82m-46-42 128-29M86 179l59 82m-85-76 59 82m-45-41 128-29M249 228v44m-146-1v32M0 320h500"/>`;}else if(kind==='agro'){objects=`<path d="M0 246c110-70 245-70 500 10M0 275c130-80 300-72 500 6M35 320c98-77 230-97 350-77M130 320c75-46 152-62 242-64M245 320c43-20 104-31 160-30M220 196V86m0 66c-45 4-74-31-70-62 37-2 63 19 70 51m0-20c36-4 64-27 62-61-33 0-58 20-62 48"/><circle cx="395" cy="76" r="28"/>`;}else{objects=`<path d="M62 230h90V125H62zm147 0h90V78h-90zm147 0h90V152h-90zM105 80l100-50 100 50 100-50M0 275h500"/><path d="m80 148 18 18 35-35m95-30 18 18 35-35m95 90 18 18 35-35"/>`;}
return `<svg viewBox="0 0 500 350" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><rect width="500" height="350" fill="${bg}"/><g stroke="${color}" stroke-width="1.3" stroke-linejoin="round">${objects}</g>${hero?`<g transform="translate(310 155)"><ellipse cx="0" cy="93" rx="76" ry="27" fill="#04283e" stroke="#3e7895"/><path d="M-76 55v36c0 38 152 38 152 0V55" fill="#0a3d58" stroke="#4e99b8"/><ellipse cy="55" rx="76" ry="27" fill="#155570" stroke="#75cde8"/><ellipse cy="55" rx="56" ry="19" stroke="#3b9cbd"/><image href="assets/tokenhub-symbol-white.svg" x="-12" y="38" width="24" height="34" transform="translate(0 55) scale(1 .6) translate(0 -55)"/></g><g stroke="#3790b1" stroke-dasharray="3 5"><path d="M80 170v105l100 45h80M380 135l45 20v100"/></g><circle cx="80" cy="170" r="5" fill="#00a2d4"/><circle cx="425" cy="255" r="5" fill="#00a2d4"/>`:`<g stroke="${light}" stroke-width="1" opacity=".5"><path d="M0 340 500 120M0 320 500 100M0 300 500 80"/></g>`}</svg>`;}
function card(o){return `<article class="offer-card"><div class="offer-art"><a class="offer-image-link" href="#${route.startsWith('/app')?'/app':''}/oferta/${o.id}" aria-label="Conhecer ${o.name}">${art(o.art)}</a><div class="art-meta"><button class="icon-button ${state.favorites.has(o.id)?'active':''}" data-favorite="${o.id}" aria-label="${state.favorites.has(o.id)?'Remover dos':'Adicionar aos'} favoritos: ${o.name}" aria-pressed="${state.favorites.has(o.id)}">${icon('heart')}</button></div></div><div class="offer-body"><h3><a href="#${route.startsWith('/app')?'/app':''}/oferta/${o.id}">${o.name}</a></h3><p class="issuer">${o.issuer.replace(/\s+demonstrativ[oa]/gi,'')}</p><div class="offer-metrics"><div><small>Rentabilidade</small><strong class="num">${number(o.rate)}<span>% a.a.</span></strong></div><div><small>Prazo</small><strong class="num">${o.term}<span> meses</span></strong></div></div><div class="progress" role="img" aria-label="${o.progress}% da meta de captação"><span style="width:${o.progress}%"></span></div><div class="progress-label"><span>${money(o.raised)} captados</span><strong>${number(o.progress)}%</strong></div><div class="card-bottom"><div>A partir de<strong class="num">${money(o.min)}</strong></div>${arrow('Ver projeto',`#${route.startsWith('/app')?'/app':''}/oferta/${o.id}`)}</div></div></article>`;}
function catalogCard(o,i){if(o.id===upOpportunity.id)return upCard(state.favorites.has(o.id),icon);return `<article class="catalog-card"><div class="catalog-image"><a class="catalog-image-link" href="#/oferta/${o.id}" aria-label="Conhecer ${o.name}">${photo(o.art,{sizes:'(max-width:760px) 100vw, (max-width:1400px) 50vw, 700px'})}</a><span class="catalog-category">${o.category}</span><button class="catalog-save ${state.favorites.has(o.id)?'active':''}" data-favorite="${o.id}" aria-label="${state.favorites.has(o.id)?'Remover dos':'Adicionar aos'} favoritos: ${o.name}" aria-pressed="${state.favorites.has(o.id)}">${icon('heart')}</button></div><div class="catalog-copy"><div class="catalog-kicker"><span>TokenHub · ${o.category}</span></div><h3><a href="#/oferta/${o.id}">${o.name}</a></h3><p class="catalog-description">${{reserva:'Desenvolvimento residencial. Uma nova perspectiva sobre o mercado imobiliário.',solar:'Geração de energia. Tecnologia conectada à economia real.',agro:'Cadeia do agronegócio. Conheça a estrutura por trás do ativo.',recebiveis:'Recebíveis empresariais. Entenda os direitos e as condições.'}[o.id]}</p><dl class="catalog-facts catalog-investment-facts" aria-label="Condições do projeto"><div><dt>Rentabilidade</dt><dd>${number(o.rate)}<small>% a.a.</small></dd></div><div><dt>Investimento mínimo</dt><dd><small>R$</small> ${number(o.min)}</dd></div><div><dt>Prazo do projeto</dt><dd>${o.term}<small> meses</small></dd></div><div><dt>Nível de risco</dt><dd>${o.risk}</dd></div></dl><p class="catalog-risk-note">Sem garantia de retorno.</p><div class="catalog-funding"><div><span>Captação</span><strong>${number(o.progress)}%</strong></div><div class="progress" role="img" aria-label="${o.progress}% da meta de captação"><span style="width:${o.progress}%"></span></div><small>${money(o.raised)} de ${money(o.goal)}</small></div><a class="catalog-link" href="#/oferta/${o.id}"><span>Conhecer o projeto</span><span class="catalog-link-arrow">${icon('arrow')}</span></a></div></article>`;}
function calculator(){return renderSimulator();}
function home(){return site(`<section class="hero hero-photo"><div class="container hero-grid"><div class="hero-copy"><h1><span class="hero-title-line">O futuro do mercado</span><em class="hero-title-line">imobiliário, chegou.</em></h1><p>Invista no mercado imobiliário de forma mais acessível, transparente e inteligente. Com a tokenização, você diversifica seu patrimônio e acessa novas oportunidades de investimento.</p><div class="row">${arrow('Explorar oportunidades','#/oportunidades','btn btn-primary')}${arrow('Como funciona','#/como-funciona','btn btn-light')}</div></div></div><div class="mobile-banner-art" aria-hidden="true"><img src="assets/photos/mobile-home.webp" width="1448" height="1086" alt="" decoding="async" fetchpriority="high"></div></section><section class="token-benefits" aria-labelledby="token-benefits-title"><div class="container"><div class="token-benefits-intro"><div><span class="eyebrow">Vantagens da tokenização</span><h2 id="token-benefits-title">Novas possibilidades para <em>o seu patrimônio.</em></h2></div><p>A tokenização transforma ativos imobiliários em oportunidades de investimento mais acessíveis, permitindo diversificar seu patrimônio e acompanhar seus investimentos com mais praticidade e transparência.</p></div><div class="token-benefits-grid"><a class="token-benefit" href="#/oportunidades" aria-label="Conhecer oportunidades de investimento com valores mais acessíveis"><div class="token-benefit-top"><span class="token-benefit-index"><strong>01</strong><span>/ ACESSO</span></span><span class="token-benefit-icon">${icon('building')}</span></div><h3>Invista com valores mais acessíveis.</h3><span class="token-benefit-cta">Explorar oportunidades <span aria-hidden="true">→</span></span></a><a class="token-benefit" href="#/oportunidades" aria-label="Explorar oportunidades para diversificar investimentos"><div class="token-benefit-top"><span class="token-benefit-index"><strong>02</strong><span>/ DIVERSIFICAÇÃO</span></span><span class="token-benefit-icon">${icon('layers')}</span></div><h3>Diversifique seu patrimônio.</h3><span class="token-benefit-cta">Ver oportunidades <span aria-hidden="true">→</span></span></a><a class="token-benefit" href="#/como-funciona" aria-label="Entender como funciona o acompanhamento transparente de investimentos"><div class="token-benefit-top"><span class="token-benefit-index"><strong>03</strong><span>/ TRANSPARÊNCIA</span></span><span class="token-benefit-icon">${icon('chart')}</span></div><h3>Acompanhe com mais transparência.</h3><span class="token-benefit-cta">Saiba como funciona <span aria-hidden="true">→</span></span></a></div></div></section><section class="section home-opportunities" aria-labelledby="home-offers-title"><div class="container"><div class="section-head home-offers-head"><div><span class="eyebrow">Explore o que vem a seguir</span><h2 id="home-offers-title">O mercado imobiliário<br>é o ponto de partida.</h2><p>Comece pelo mercado imobiliário e conheça outros cenários de ativos desta demonstração.</p></div></div><div class="offer-grid">${offers.slice(0,3).map(card).join('')}</div><div class="home-offers-action">${arrow('Ver oportunidades','#/oportunidades','btn btn-primary')}</div><p class="footnote">Sem garantia de retorno. Investimentos podem gerar perdas e apresentar baixa liquidez.</p></div></section><section class="section wash home-journey"><div class="container"><div class="section-head home-journey-head"><div><span class="eyebrow">Da descoberta ao acompanhamento</span><h2>Uma jornada que faz sentido.</h2><p>Menos etapas sem contexto.<br>Mais clareza a cada decisão.</p></div></div><div class="grid4">${[['Crie sua conta','Comece com as informações essenciais, em uma jornada guiada.'],['Conheça cada projeto','Explore condições, documentação e fatores de risco.'],['Escolha com clareza','Confira valores e condições antes de confirmar uma operação.'],['Acompanhe seus ativos','Encontre aplicações, movimentações e documentos em um só lugar.']].map(([t,p],i)=>`<div class="step-card"><span class="step-number">0${i+1}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div></section><section class="section simulator-section"><div class="container">${calculator()}</div></section><section class="section wash"><div class="container trust-grid"><div><span class="eyebrow">Transparência em primeiro lugar</span><h2>Confiança começa<br>com informação.</h2><p class="lead">Tecnologia precisa aproximar. Por isso, cada etapa deve ajudar você a entender o que está fazendo.</p>${arrow('Conheça a TokenHub','#/quem-somos','arrow-link mt20')}</div><div class="trust-points">${[['doc','Documentação acessível','Condições, prazos e direitos apresentados junto de cada projeto.'],['shield','Riscos em evidência','Uma visão clara dos fatores que podem afetar cada oportunidade.'],['chart','Acompanhamento organizado','Saldo, aplicações e movimentações com papéis bem definidos.']].map(([i,t,p])=>`<div class="trust-point">${icon(i)}<div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></div></section>${officialServices(icon)}${cta()}${faqSection()}`);}
function pageHero(eyebrow,title,description=''){const heroArtwork={'/oportunidades':'opportunities','/como-funciona':'how','/para-empresas':'companies','/quem-somos':'about'}[route];return `<section class="page-hero${heroArtwork?' page-hero-art page-hero-'+heroArtwork:''}"><div class="container"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${heroArtwork?`<div class="mobile-banner-art" aria-hidden="true"><img src="assets/photos/${heroArtwork==='about'?'header-about-employees.png':heroArtwork==='how'?'header-how-user-v11.webp':heroArtwork==='companies'?'mobile-companies-conversation-v14.webp':'mobile-'+heroArtwork+'.webp'}" width="1448" height="1086" alt="" decoding="async"></div>`:''}</section>`;}
function offerFilters(){if(route==='/oportunidades')return catalogFilters();return `<div class="filters" aria-label="Categorias de ofertas">${['Todas','Imobiliário','Energia','Agronegócio','Recebíveis'].map(c=>`<button class="chip ${state.filter===c?'active':''}" aria-pressed="${state.filter===c}" data-category="${c}">${c==='Todas'?'Todas as categorias':c}</button>`).join('')}</div><div class="toolbar"><label class="search-wrap"><span class="sr-only">Buscar projeto</span>${icon('search')}<input id="offer-search" type="search" placeholder="Buscar projeto ou categoria" value="${esc(state.query)}"></label><select class="tool-select" id="offer-sort" aria-label="Ordenar ofertas"><option value="default" ${state.sort==='default'?'selected':''}>Ordem de apresentação</option><option value="min" ${state.sort==='min'?'selected':''}>Menor valor inicial</option><option value="term" ${state.sort==='term'?'selected':''}>Menor prazo</option><option value="recent" ${state.sort==='recent'?'selected':''}>Encerramento mais próximo</option></select><button class="btn btn-outline btn-sm" data-action="only-favorites" aria-pressed="${state.onlyFavorites}">${icon('heart')}${state.onlyFavorites?'Todos os projetos':'Favoritos'}</button></div><div id="offers-results" aria-live="polite">${offerResults()}</div>`;}
function catalogFilters(){return `<section class="catalog-filter-panel" aria-labelledby="catalog-filter-title"><div class="catalog-filter-top"><h3 id="catalog-filter-title">Encontre seu próximo projeto</h3><button type="button" class="catalog-reset" data-action="reset-filters">Limpar filtros ${icon('close')}</button></div><div class="catalog-filter-fields"><label class="catalog-filter-field"><span>Buscar oportunidade</span><span class="catalog-search-input">${icon('search')}<input id="offer-search" type="search" placeholder="Nome do projeto ou categoria" value="${esc(state.query)}"></span></label><label class="catalog-filter-field"><span>Ordenar por</span><select id="offer-sort" aria-label="Ordenar ofertas"><option value="default" ${state.sort==='default'?'selected':''}>Ordem de apresentação</option><option value="min" ${state.sort==='min'?'selected':''}>Menor valor inicial</option><option value="term" ${state.sort==='term'?'selected':''}>Menor prazo</option><option value="recent" ${state.sort==='recent'?'selected':''}>Encerramento mais próximo</option></select></label><div class="catalog-filter-field"><span>Sua seleção</span><button type="button" class="catalog-favorites" data-action="only-favorites" aria-pressed="${state.onlyFavorites}">${icon('heart')}Somente favoritos</button></div></div><div class="catalog-category-row"><span class="catalog-category-label">Categorias</span><div class="filters" role="group" aria-label="Categorias de ofertas">${['Todas','Imobiliário','Energia','Agronegócio','Recebíveis'].map(c=>`<button type="button" class="chip ${state.filter===c?'active':''}" aria-pressed="${state.filter===c}" data-category="${c}">${c==='Todas'?'Todas':c}</button>`).join('')}</div></div></section><div id="offers-results" aria-live="polite">${offerResults()}</div>`;}
function matchingOffers(){let list=(route==='/oportunidades'?[upOpportunity,...offers.filter(o=>o.id!=='reserva')]:offers).filter(o=>(state.filter==='Todas'||o.category===state.filter)&&(!state.onlyFavorites||state.favorites.has(o.id))&&`${o.name} ${o.category}`.toLocaleLowerCase('pt-BR').includes(state.query.toLocaleLowerCase('pt-BR')));if(state.sort==='min')list.sort((a,b)=>a.min-b.min);if(state.sort==='term')list.sort((a,b)=>a.term-b.term);if(state.sort==='recent')list.sort((a,b)=>a.remaining-b.remaining);return list;}
function offerResults(){const list=matchingOffers();return `<p class="results-count mb24">${list.length} ${route==='/oportunidades'?(list.length===1?'projeto':'projetos'):(list.length===1?'projeto demonstrativo':'projetos demonstrativos')}</p>${list.length?`<div class="${route==='/oportunidades'?'catalog-grid':'offer-grid'}">${route==='/oportunidades'?list.map(catalogCard).join(''):list.map(card).join('')}</div>`:empty('Nenhum projeto encontrado','Tente outra busca ou categoria. Você também pode limpar os filtros.','Limpar filtros','reset-filters')}<p class="footnote">${route==='/oportunidades'?'Residencial UP: informações do anúncio da A12, sujeitas à confirmação. Os demais projetos e indicadores são fictícios. Esta apresentação não constitui oferta de investimento.':'Os projetos e seus indicadores são fictícios. A apresentação não constitui uma oferta de investimento.'}</p>`;}
function opportunities(inApp=false){const body=`${inApp?heading('Oportunidades','Explore projetos. Compare antes de decidir.','Economia real',arrow('Minha carteira','#/app/carteira','btn btn-dark')):''}${offerFilters()}`;return inApp?shell(body,'Oportunidades'):site(`${pageHero('Economia real, novas conexões','Oportunidades para<br><em>diversificar seu portfólio.</em>','As melhores oportunidades nem sempre são as mais evidentes.<br>Reconhecê-las exige visão, conhecimento e capacidade.')}<section class="section opportunities-catalog"><div class="container"><div class="catalog-heading"><div><span class="eyebrow">Explore com perspectiva</span><h2>Projetos para olhar<br>mais de perto.</h2><p class="catalog-intro">Conheça o ativo, entenda a estrutura e compare antes de escolher.</p></div></div>${body}</div></section>`);}
function offerDetail(id,inApp=false){if(id===upOpportunity.id&&!inApp)return site(upDetail(icon));const o=offers.find(o=>o.id===id);if(!o)return notFound();const tabs=['Visão geral','Documentos','Riscos','Atualizações'];const body=`<div class="breadcrumbs"><a href="#${inApp?'/app':''}/oportunidades">Oportunidades</a><span>/</span><span>${o.name}</span></div><div class="app-heading"><div><span class="eyebrow">Projeto demonstrativo · ${o.category}</span><h1>${o.name}</h1><p>${o.issuer}</p></div><button class="btn btn-outline btn-sm" data-favorite="${o.id}" aria-pressed="${state.favorites.has(o.id)}">${icon('heart')}${state.favorites.has(o.id)?'Salvo nos favoritos':'Salvar projeto'}</button></div><div class="detail-layout"><div><div class="detail-art">${photo(o.art,{eager:true,sizes:"(max-width:900px)100vw,75vw"})}</div><div class="tabs" role="tablist" aria-label="Informações do projeto">${tabs.map((t,i)=>`<button id="detail-tab-${i}" role="tab" aria-controls="detail-panel" aria-selected="${state.detailTab===t}" tabindex="${state.detailTab===t?0:-1}" class="tab ${state.detailTab===t?'active':''}" data-detail-tab="${t}">${t}</button>`).join('')}</div><div class="panel" role="tabpanel" id="detail-panel" aria-labelledby="detail-tab-${tabs.indexOf(state.detailTab)}">${detailContent(o)}</div></div><aside class="detail-side panel" aria-label="Condições do projeto"><span class="eyebrow">Condições ilustrativas</span><h2 class="num" style="font-size:38px">${number(o.rate)}<span style="font-size:16px">% a.a.</span></h2><p class="small">Retorno hipotético, sem garantia.</p><div class="mt20">${[['Prazo',o.term+' meses'],['Valor mínimo',money(o.min)],['Categoria',o.category],['Risco',o.risk]].map(([k,v])=>`<div class="summary-line"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="mt20"><div class="progress" role="img" aria-label="${o.progress}% da meta ilustrativa"><span style="width:${o.progress}%"></span></div><div class="progress-label"><span>Meta ilustrativa: ${money(o.goal)}</span><strong>${number(o.progress)}%</strong></div></div><div class="risk-note">Risco de perda do capital e baixa liquidez. Leia os documentos antes de qualquer decisão.</div><button class="btn btn-primary" data-invest="${o.id}">Simular aplicação ${icon('arrow')}</button><p class="footnote">Nenhum recurso é movimentado nesta demonstração.</p></aside></div>`;return inApp?shell(body,o.name):site(`<section class="section"><div class="container">${body}</div></section>`);}
function detailContent(o){if(state.detailTab==='Documentos')return `<h3>Documentação do projeto</h3><p>Organização dos documentos do projeto. Os arquivos abaixo são modelos demonstrativos.</p>${['Informações essenciais','Condições da oferta','Matriz de riscos'].map((d,i)=>`<div class="document-row"><div class="row">${icon('doc')}<div><strong>${d}</strong><p>Modelo ilustrativo · TXT</p></div></div><button class="icon-button" data-document="${o.id}:${i}" aria-label="Baixar modelo: ${d}">${icon('download')}</button></div>`).join('')}`;if(state.detailTab==='Riscos')return `<h3>O que considerar</h3><p>Retorno e liquidez dependem da estrutura da operação. A lista é ilustrativa e não substitui os documentos de uma oferta real.</p>${[['Crédito','O emissor pode não cumprir suas obrigações.'],['Liquidez','Pode não haver compradores ou resgate antecipado.'],['Mercado','Mudanças econômicas podem afetar o ativo e seus resultados.'],['Operação e tecnologia','Problemas operacionais podem afetar registros, execução e disponibilidade.']].map(([t,p])=>`<div class="document-row"><div><strong>${t}</strong><p>${p}</p></div>${badge('Atenção','amber')}</div>`).join('')}`;if(state.detailTab==='Atualizações')return `<h3>Comunicação ao investidor</h3><div class="document-row"><div><span class="eyebrow">Atualização do projeto</span><strong>Documentação organizada para consulta</strong><p>Área destinada a comunicados do emissor e eventos do projeto.</p></div></div><p>Em uma oferta real, cada atualização deverá registrar data, autoria e documentos relacionados.</p>`;return `<h3>Sobre o projeto</h3><p>${o.description}</p><h3 class="mt32">Entenda a estrutura</h3><div class="mt20">${[['Objetivo','Financiamento de um projeto demonstrativo'],['Representação','Direitos definidos em contrato'],['Pagamento','Cronograma definido por oferta'],['Custos e tributos','A confirmar na documentação real']].map(([k,v])=>`<div class="summary-line"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><p>Antes de investir, confira a capacidade do emissor, as garantias, os custos, os riscos e as regras de saída. A tecnologia de tokenização não garante o desempenho do ativo.</p>`;}
function how(){const steps=[['Ativo e viabilidade','Identificação do ativo e avaliação econômica e jurídica da operação.','Tudo começa pelo ativo.','building'],['Estrutura e documentos','Definição dos direitos, obrigações, riscos, custos e condições.','Os direitos precisam estar claros.','doc'],['Representação digital','Registro dos direitos conforme a estrutura tecnológica adotada.','A tecnologia conecta a estrutura.','layers'],['Apresentação da oferta','Informações organizadas para análise e decisão do investidor.','Informação antes da decisão.','shield'],['Aplicação e acompanhamento','Conferência das condições e acompanhamento de eventos e pagamentos.','A jornada continua depois da escolha.','chart']];return site(`${pageHero('Como funciona','Do imóvel ao token:<br><em class="page-title-accent" style="color:#00a2d4;font-style:normal;font-weight:800">uma jornada digital.</em>','A tokenização representa direitos sobre ativos reais em unidades digitais. Entenda a estrutura, conheça os documentos e acompanhe cada etapa.')}<section class="section how-intro"><div class="container"><span class="eyebrow">Entenda a estrutura</span><h2>O ativo é real.<br><span>A jornada é digital.</span></h2><p class="lead">Cada token precisa de contexto: qual direito representa, como se relaciona ao ativo e quais condições estão previstas.</p><div class="how-landscape" data-site-parallax><figure class="asset-photo"><img src="assets/photos/how-structure-user-v14.webp" width="2048" height="683" alt="Edifício residencial ao entardecer conectado a representações digitais de imóveis e documentos" loading="lazy" decoding="async"></figure><span>O imóvel é o ponto de partida.<br>A informação acompanha todo o caminho.</span></div></div></section><section class="section how-process"><div class="container"><div class="how-process-heading"><span class="eyebrow">Acompanhe o caminho</span><h2>Da origem.<br><span>À sua carteira.</span></h2><p>Cinco etapas para entender como um ativo chega à experiência digital.</p><div class="how-progress" aria-hidden="true"><span></span></div><nav class="how-step-nav" aria-label="Etapas da tokenização">${steps.map((v,i)=>`<a href="#how-step-${i}" data-step-jump="${i}" aria-label="Etapa ${i+1}: ${v[0]}">0${i+1}</a>`).join('')}</nav></div><div class="how-step-list">${steps.map(([t,p,k,ic],i)=>`<article class="how-step" id="how-step-${i}"><span class="how-step-number" aria-hidden="true">0${i+1}</span><div class="how-step-body">${icon(ic)}<span class="eyebrow">${k}</span><h3>${t}</h3><p>${p}</p></div></article>`).join('')}</div></div></section><section class="section how-questions"><div class="container"><span class="eyebrow">Antes de escolher</span><h2>Faça as<br>perguntas certas<span>.</span></h2><p class="lead">Uma boa decisão começa com uma boa conversa.<br>Abra cada pergunta e descubra o que observar.</p><div class="question-conversation">${[['O que estou adquirindo?','Leia os contratos e identifique o direito e as obrigações envolvidos.','Comece pelos documentos.'],['Quais riscos assumo?','Avalie emissor, garantias, liquidez, mercado e prazo.','Olhe além do potencial.'],['Como acompanho?','Confira a forma de registro, os comunicados e os documentos da operação.','Saiba onde encontrar informação.']].map(([t,p,k],i)=>`<details class="question-bubble" ${i===0?'open':''}><summary><span class="question-index">0${i+1}</span>${t}<span class="question-plus" aria-hidden="true">+</span></summary><div class="question-answer"><span>${k}</span><p>${p}</p></div></details>`).join('')}</div></div></section>${howDiscovery()}${cta()}`);}
function howDiscovery(){const steps=[['Abra sua conta','Acesse o início do cadastro.','Seu primeiro passo','user'],['Preencha seus dados','Conheça as informações da jornada.','Tudo começa com você','doc'],['Ative seu acesso','Na operação oficial, a etapa prevê confirmação por token.','Uma etapa de confirmação','shield'],['Explore e acompanhe','Conheça os ativos e sua carteira.','Novas possibilidades à vista','building']];return `<section class="section how-discovery"><div class="container"><span class="eyebrow">Comece pela sua conta</span><h2>Do cadastro<br>à descoberta.</h2><p class="lead">A jornada começa com cadastro e ativação por token. Aqui você pode conhecer as telas sem criar uma conta real.</p><div class="discovery-layout"><div class="discovery-tabs" role="tablist" aria-label="Passos do cadastro" aria-orientation="vertical">${steps.map(([t,p],i)=>`<button class="discovery-tab" id="discovery-tab-${i}" role="tab" aria-selected="${i===0}" aria-controls="discovery-panel-${i}" tabindex="${i===0?0:-1}" data-discovery="${i}"><span>0${i+1}</span><span><strong>${t}</strong><small>${p}</small></span><b aria-hidden="true">↗</b></button>`).join('')}</div><div class="discovery-panels">${steps.map(([t,p,k,ic],i)=>`<div class="discovery-panel" role="tabpanel" id="discovery-panel-${i}" aria-labelledby="discovery-tab-${i}" tabindex="0" ${i?'hidden':''}><span class="discovery-watermark" aria-hidden="true">0${i+1}</span><div class="discovery-preview">${icon(ic)}<span class="eyebrow">${k}</span><h3>${t}</h3><div class="preview-lines" aria-hidden="true"><i></i><i></i><i></i></div><p>${p}</p><span class="discovery-count">PASSO 0${i+1} / 04</span></div></div>`).join('')}<div class="discovery-controls"><span>Explore cada etapa</span><button type="button" data-discovery-next aria-label="Ver próximo passo">Próximo passo →</button></div></div></div><a class="btn btn-primary mt32" href="#/cadastro">Conhecer o cadastro →</a></div></section>`;}
function about(){return site(`<section class="about-hero"><div class="container about-hero-grid"><div class="about-hero-copy"><span class="eyebrow">Sobre a TokenHub</span><h1>O futuro de investir.<br><em>Mais perto de você.</em></h1><p>Conectamos pessoas ao mercado imobiliário por meio da tokenização. Com tecnologia para simplificar e informação para escolher.</p>${arrow('Conheça nossa visão','#/quem-somos?visao','arrow-link about-vision-link')}</div><div class="about-hero-image"><img src="assets/photos/about-hero-user-v10.webp" alt="Duas pessoas sorrindo enquanto consultam um tablet em um escritório" width="2048" height="768" fetchpriority="high"></div></div></section><section class="section about-intro" id="tokenhub-visao"><div class="container"><span class="eyebrow">Quem somos</span><h2 data-about-reveal>Ativos reais.<br>Tecnologia que aproxima.<br><span>Relações que constroem.</span></h2><p class="about-intro-text" data-about-reveal>A TokenHub aproxima pessoas de novas possibilidades no mercado imobiliário. Reunimos tecnologia, conhecimento e informação em uma experiência pensada para tornar cada etapa mais clara — da descoberta de um projeto ao acompanhamento dos ativos.</p><div class="about-team" data-about-reveal><img src="assets/photos/about-team-user-v10.webp" alt="Três profissionais reunidos no escritório com um tablet e um notebook" width="1727" height="911" loading="lazy" decoding="async"><div class="about-team-caption"><span>Conexões humanas.</span><strong>Possibilidades reais.</strong></div></div></div></section><section class="about-purpose"><div class="container about-purpose-grid"><div class="about-orbit" aria-hidden="true"><svg class="orbit-diagram" viewBox="0 0 520 420"><g class="orbit-track" data-orbit-track="a" transform="rotate(-28 260 210)"><ellipse cx="260" cy="210" rx="185" ry="112"/></g><g class="orbit-track orbit-track-secondary" data-orbit-track="b" transform="rotate(45 260 210)"><ellipse cx="260" cy="210" rx="210" ry="130"/></g><g class="orbit-node" data-orbit-node="people" transform="translate(77 241)"><circle r="5"/><g transform="translate(-40 13)"><rect width="80" height="32" rx="16"/><text x="40" y="20">Pessoas</text></g></g><g class="orbit-node" data-orbit-node="technology" transform="translate(430 148)"><circle r="4"/><g transform="translate(-52 -45)"><rect width="104" height="32" rx="16"/><text x="52" y="20">Tecnologia</text></g></g><g class="orbit-node" data-orbit-node="assets" transform="translate(160 289)"><circle r="4"/><g transform="translate(-51 13)"><rect width="102" height="32" rx="16"/><text x="51" y="20">Ativos reais</text></g></g></svg><div class="orbit-core">${mark}</div></div><div class="about-purpose-copy"><span class="eyebrow">O que nos move</span><h2 data-about-reveal>Um novo acesso.<br>Uma nova perspectiva.</h2><p data-about-reveal>Acreditamos que o futuro do investimento começa quando mais pessoas conseguem entender suas possibilidades.</p><p data-about-reveal>Por isso, nossa proposta vai além da conexão digital: queremos aproximar o mercado imobiliário de quem busca conhecer, participar e acompanhar. Com aprendizado, transparência e uma jornada intuitiva.</p>${arrow('Entenda como funciona','#/como-funciona','arrow-link')}</div></div></section><section class="section wash"><div class="container"><div class="section-head"><div><span class="eyebrow">Nossa proposta de valor</span><h2>Mais acesso.<br>Mais conhecimento.</h2></div></div><div class="grid4 about-benefits">${[['wallet','Conta sem custo de manutenção','Abertura e manutenção gratuitas, com tarifas de negociação e saque conforme a tabela vigente.'],['shield','Proteção dos ativos','Segurança da carteira e custódia como compromissos da operação. Consulte as condições do serviço.'],['doc','Conhecimento para investir','Conteúdo sobre tokens, blockchain e investimentos para apoiar o aprendizado.'],['check','Ética e compliance','Compromisso com prevenção a fraudes e à lavagem de dinheiro.']].map(([i,t,p])=>`<article class="panel official-service">${icon(i)}<h3>${t}</h3><p>${p}</p></article>`).join('')}</div></div></section><section class="section"><div class="container cols"><div><span class="eyebrow">TokenHub</span><h2>Vamos conversar<br>sobre o próximo passo.</h2><p class="lead">Conheça nossa proposta, tire suas dúvidas e fale com a equipe.</p>${arrow('Entre em contato','#/contato','btn btn-dark mt32')}</div><div class="panel"><h3>Informações institucionais</h3><div class="mt20">${companyIdentity()}</div></div></div></section>`);}
function companies(){return site(`${pageHero('Para empresas e originadores','Seu projeto merece<br><em class="page-title-accent">uma conversa com futuro.</em>','Apresente seu ativo e o objetivo da captação. Uma estrutura adequada começa pela compreensão do projeto.')}${renderCompanies()}`);}
function contactForm(kind='contact'){return `<form data-form="${kind}"><div class="field"><label for="contact-name">Nome completo</label><input id="contact-name" name="name" autocomplete="name" required minlength="3" maxlength="100" placeholder="Como podemos chamar você?"></div><div class="form-grid"><div class="field"><label for="contact-email">E-mail profissional</label><input id="contact-email" name="email" type="email" autocomplete="email" required maxlength="180" placeholder="voce@empresa.com.br"></div><div class="field"><label for="contact-phone">Telefone</label><input id="contact-phone" name="phone" type="tel" autocomplete="tel" placeholder="(11) 99999-9999" required minlength="10" maxlength="22"></div></div><div class="field mt20"><label for="contact-kind">${kind==='company'?'Tipo de ativo':'Como podemos ajudar?'}</label><select id="contact-kind" name="kind">${(kind==='company'?['Imobiliário','Agronegócio','Energia','Recebíveis','Outro ativo']:['Conhecer os projetos','Apresentar um ativo','Suporte à conta','Outra dúvida']).map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label for="contact-message">${kind==='company'?'Resumo do projeto':'Sua mensagem'}</label><textarea id="contact-message" name="message" required minlength="10" maxlength="2000" placeholder="Conte um pouco sobre o que você precisa."></textarea></div><label class="checkbox"><input type="checkbox" required><span>Entendo que este é um formulário de demonstração e que nenhuma mensagem será enviada.</span></label><button class="btn btn-dark full mt20" type="submit">Revisar demonstração ${icon('arrow')}</button><div class="form-feedback" role="status"></div></form>`;}
function contact(){return site(`${pageHero('Entre em contato','Converse com a TokenHub.','Conheça a empresa, tire dúvidas sobre a proposta e organize sua mensagem para a equipe.')}<section class="section"><div class="container cols"><div>${companyIdentity()}<span class="eyebrow mt32">Cada conversa tem um caminho</span><h2>Conte com uma<br>experiência mais clara.</h2><div class="trust-points mt32">${[['layers','Projetos e oportunidades','Entenda a proposta de cada ativo.'],['building','Empresas e originadores','Apresente o objetivo do seu projeto.'],['user','Sua conta','Encontre ajuda para a sua jornada.']].map(([i,t,p])=>`<div class="trust-point">${icon(i)}<div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></div><div class="panel">${contactForm()}</div></div></section>`);}
function faqSection(){return `<section class="section home-faq" id="perguntas-frequentes" aria-labelledby="home-faq-title"><div class="container"><div class="section-head"><div><span class="eyebrow">Perguntas frequentes</span><h2 id="home-faq-title">Sua dúvida tem espaço aqui.</h2><p>Conceitos, jornada e segurança. Encontre as respostas para dar o próximo passo com mais contexto.</p></div></div><label class="search-wrap mb24" style="max-width:620px"><span class="sr-only">Buscar perguntas</span>${icon('search')}<input type="search" id="faq-search" placeholder="O que você quer entender?" value="${esc(state.faqQuery)}"></label><div class="faq-layout"><aside class="faq-side" aria-label="Categorias de ajuda">${['Todas','Conceitos','Investidores','Empresas','Segurança'].map(t=>`<button class="chip ${state.faqCategory===t?'active':''}" aria-pressed="${state.faqCategory===t}" data-faq-category="${t}">${t}</button>`).join('')}</aside><div id="faq-results" aria-live="polite">${faqResults()}</div></div><div class="panel mt32 row between wrap"><div><h3>Precisa de outra informação?</h3><p>Organize sua dúvida para conversar com a equipe.</p></div>${arrow('Fale com a TokenHub','#/contato','btn btn-outline')}</div></div></section>`;}
function faqPage(){return site(`${pageHero('Central de ajuda','Sua dúvida tem espaço aqui.')}${faqSection()}`);}
function faqResults(){const items=faq.filter(([q,a,c])=>(state.faqCategory==='Todas'||c===state.faqCategory)&&`${q} ${a}`.toLowerCase().includes(state.faqQuery.toLowerCase()));return items.length?items.map(([q,a])=>`<details class="faq-item"><summary>${q}</summary><p>${a}</p></details>`).join(''):empty('Nenhuma pergunta encontrada','Tente buscar por um termo mais curto.');}
function contentPage(id){if(id){const a=articles.find(a=>a.id===id);if(!a)return notFound();return site(`${pageHero(a.tag,a.title,a.intro)}<section class="section"><article class="container prose"><div class="article-detail-photo">${photo(a.id==="ativos"?"urban":a.id==="riscos"?"flow":"people",{eager:true,sizes:"(max-width:760px)100vw,800px"})}</div><p>${a.body}</p><div class="risk-note">Conteúdo introdutório da demonstração. Não constitui recomendação de investimento.</div>${arrow('Voltar ao conhecimento','#/conteudos')}</article></section>`);}return site(`${pageHero('Conhecimento que conecta','Token Academy','Aprenda sobre ativos tokenizados, blockchain e investimentos. Comece pelos conceitos e pelos cuidados de cada decisão.')}<section class="section"><div class="container grid3">${articles.map(a=>`<article class="article-card"><div class="article-photo">${photo(a.id==="ativos"?"urban":a.id==="riscos"?"flow":"people")}</div><span class="eyebrow">${a.tag}</span><h3>${a.title}</h3><p>${a.intro}</p>${arrow('Ler conteúdo','#/conteudos/'+a.id)}</article>`).join('')}</div></section>${cta()}`);}
function legal(kind){const document=documents[kind];if(document)return site(`${pageHero(kind==='material'?'Token Academy':'Transparência',document.title,document.subtitle)}<section class="section"><div class="container prose">${document.paragraphs.map(paragraph=>`<p>${esc(paragraph)}</p>`).join('')}${kind==='privacidade'?`<h2>Dados nesta demonstração</h2><p>Os formulários são processados apenas no navegador. Senhas não são salvas nem enviadas. Favoritos são guardados neste navegador e podem ser apagados na área Sobre esta versão. Não há rastreadores, cookies de publicidade ou integração com a conta Tokeniza.</p>`:''}${kind==='material'?`<h2>Comece por estes conteúdos</h2><div class="stack mt20">${articles.map(article=>`<article class="panel"><span class="eyebrow">${article.tag}</span><h3>${article.title}</h3><p>${article.intro}</p>${arrow('Ler conteúdo','#/conteudos/'+article.id,'arrow-link mt20')}</article>`).join('')}</div>`:''}<div class="row wrap mt32">${arrow('Fale com a equipe','#/contato','btn btn-dark')}${arrow(kind==='material'?'Token Academy':'Sobre a demonstração',kind==='material'?'#/conteudos':'#/sobre-prototipo','btn btn-outline')}</div></div></section>`);if(kind!=='riscos')return notFound();return site(`${pageHero('Transparência','Aviso de riscos','Entenda os riscos e as condições dos cenários apresentados nesta experiência.')}<section class="section"><div class="container prose"><h2>Todo ativo precisa de análise</h2><p>Investimentos podem envolver perda parcial ou total do capital, inadimplência do emissor, baixa liquidez e riscos operacionais e tecnológicos. Projeções não garantem retorno. Tokenização e registro digital não afastam esses riscos.</p><h2>Condições por oferta</h2><p>Direitos, obrigações, custos, garantias e regras de saída dependem dos documentos da operação. Os cenários desta interface não representam ofertas reais.</p>${arrow('Sobre a demonstração','#/sobre-prototipo')}</div></section>`);}
function prototypeInfo(){return site(`${pageHero('Escopo e transparência','Uma proposta para explorar.','Site público, cadastro e área interna conectados por uma identidade TokenHub.')}<section class="section"><div class="container prose"><h2>O que você pode experimentar</h2><p>Navegue pelas oportunidades, use filtros e favoritos, simule cenários, percorra o cadastro e explore carteira, extrato, marketplace, conta digital, indicações, perfil e informe demonstrativo.</p><h2>Como os dados funcionam</h2><p>Ofertas, métricas e operações são fictícias. Os dados de formulários ficam apenas na memória da página. Senhas são descartadas após a validação local. Somente os favoritos são guardados neste navegador.</p><h2>O que depende da operação real</h2><p>Autenticação, verificação de identidade, pagamentos, custódia, emissão e negociação de tokens, documentação, tributação e serviços bancários precisam de contratos, provedores e serviços próprios. Esta versão não se conecta às APIs da Tokeniza.</p><h2>Base do levantamento</h2><p>Site público e cadastro foram inspecionados. A plataforma autenticada foi observada na janela Chrome autorizada. A REA registrou evidências dos scripts distribuídos; as capturas do Windows complementam a inspeção visual. Não houve acesso ao código de servidor.</p><button class="btn btn-outline" data-action="clear-demo">Apagar favoritos deste navegador</button>${arrow('Explorar a plataforma','#/app','btn btn-dark mt20')}</div></section>`);}
function authVisual(){return `<aside class="auth-visual photo-auth">${photo("people",{eager:true,className:"auth-photo",sizes:"50vw"})}<div class="auth-panel-copy"><span class="eyebrow">Ativos reais. Novas possibilidades.</span><h2>Uma conexão<br>com o seu futuro.</h2><p>Conheça a tokenização de imóveis e explore os recursos da plataforma. Informação para aprender, planejar e acompanhar.</p><div class="trust-points">${[['doc','Informação antes da decisão'],['layers','Toda a jornada em um só lugar'],['shield','Clareza em cada etapa']].map(([i,t])=>`<div class="trust-point">${icon(i)}<span>${t}</span></div>`).join('')}</div>${mark}</div></aside>`;}
function auth(mode='login'){let content='';if(mode==='login')content=`<h1>Bom ter você de volta.</h1><p>Acesse a experiência de demonstração TokenHub.</p><form data-form="login"><div class="field"><label for="login-email">E-mail</label><input type="email" name="email" id="login-email" required autocomplete="off" placeholder="Use um e-mail fictício"></div><div class="field"><label for="login-password">Senha de demonstração</label>${passwordField('login-password','password')}<small class="hint">Use uma senha fictícia com pelo menos 8 caracteres.</small></div><div class="row between mb24"><label class="checkbox no-margin"><input type="checkbox"><span>Lembrar preferência nesta sessão</span></label><a class="inline-link small" href="#/recuperar-senha">Esqueci a senha</a></div><button type="submit" class="btn btn-dark">Entrar na demonstração ${icon('arrow')}</button></form><div class="divider">ou conheça sem preencher</div><a class="btn btn-outline" href="#/app">Explorar a plataforma ${icon('arrow')}</a><p class="fine">Ainda não conhece a experiência? <a href="#/cadastro">Criar conta de demonstração</a></p>`;else if(mode==='forgot')content=`<h1>Vamos ajudar você.</h1><p>Veja como funciona a recuperação de acesso.</p><form data-form="forgot"><div class="field"><label for="recover-email">E-mail da conta de demonstração</label><input id="recover-email" type="email" name="email" placeholder="seuemail@dominio.com" required></div><button type="submit" class="btn btn-dark">Demonstrar recuperação ${icon('arrow')}</button><div class="form-feedback" role="status"></div></form><p class="fine"><a href="#/entrar">Voltar para entrar</a></p>`;else content=registration();return `${demo()}<main id="main" class="auth" tabindex="-1"><section class="auth-main">${logo()}<div class="auth-form">${content}</div><a class="auth-back" href="#/">← Voltar ao site TokenHub</a></section>${authVisual()}</main>`;}
function passwordField(id,name){return `<div class="password-wrap"><input type="password" id="${id}" name="${name}" required minlength="8" maxlength="128" autocomplete="off" placeholder="Crie uma senha fictícia"><button type="button" data-password="${id}" aria-label="Mostrar senha" aria-pressed="false">${icon('eye')}</button></div>`;}
function registration(){const step=state.registrationStep;if(step===4)return `<span class="eyebrow">Jornada concluída</span><h1>Tudo pronto para explorar.</h1><p>O cadastro demonstrativo terminou. Nenhuma conta real foi criada e nenhum dado foi enviado.</p><a href="#/app" class="btn btn-dark">Conhecer minha área ${icon('arrow')}</a><p class="fine">Você pode explorar os recursos com dados fictícios.</p>`;return `<div class="wizard-steps" aria-label="Etapa ${step} de 3">${[1,2,3].map(i=>`<span class="${i<=step?'active':''}"></span>`).join('')}</div><span class="eyebrow">Etapa ${step} de 3 · Demonstração</span><h1>${['Vamos nos conhecer.','Seu acesso, com clareza.','Confira o próximo passo.'][step-1]}</h1><p>${['Use dados fictícios para explorar a jornada.','Nenhum dado ou senha será enviado ou salvo.','Entenda a verificação antes de começar.'][step-1]}</p><form data-form="register">${step===1?`<div class="field"><label for="reg-country">Nacionalidade</label><select id="reg-country" name="nationality"><option>Brasil</option><option>Outro país</option></select></div><div class="field"><label for="reg-name">Nome completo</label><input id="reg-name" name="name" required minlength="3" maxlength="100" placeholder="Nome completo" autocomplete="off"></div><div class="field"><label for="reg-username">Nome de usuário</label><input id="reg-username" name="username" required minlength="3" maxlength="30" pattern="[A-Za-z0-9_.]+" placeholder="seu.nome" autocomplete="off" aria-describedby="username-hint"><small class="hint" id="username-hint">Letras sem acentos, números, ponto e sublinhado.</small></div><div class="field"><label for="reg-ref">Indicação <span class="small">(opcional)</span></label><input id="reg-ref" name="referral" maxlength="40" placeholder="Código de quem indicou"></div>`:step===2?`<div class="field"><label for="reg-type">Tipo de conta</label><select id="reg-type" name="type"><option>Pessoa física</option><option>Pessoa jurídica</option></select></div><div class="field"><label for="reg-email">E-mail</label><input id="reg-email" name="email" type="email" required placeholder="seuemail@dominio.com" autocomplete="off"></div><div class="field"><label for="reg-phone">Celular</label><input id="reg-phone" name="phone" type="tel" required minlength="10" maxlength="22" placeholder="(11) 99999-9999" autocomplete="off"></div><div class="field"><label for="reg-password">Senha fictícia</label>${passwordField('reg-password','password')}</div><div class="field"><label for="reg-confirm">Confirmar senha fictícia</label>${passwordField('reg-confirm','confirmation')}</div>`:`<div class="notice"><span>${icon('shield')}</span><div><strong>A verificação vem antes das operações.</strong><p>Em uma plataforma operacional, dados e documentos de identidade precisam ser verificados antes da liberação de funcionalidades.</p></div></div><div class="native-info">Nesta demonstração, você não envia documentos, não recebe e-mails e não abre uma conta real.</div><label class="checkbox mb24"><input type="checkbox" required><span>Li os <a href="#/legal/termos" target="_blank" rel="noopener">termos demonstrativos</a> e entendo os limites desta versão.</span></label><label class="checkbox mb24"><input type="checkbox" required><span>Entendo que investimentos podem apresentar risco de perda e baixa liquidez.</span></label>`}<div id="registration-error" role="alert"></div><button class="btn btn-dark" type="submit">${step===3?'Concluir demonstração':'Continuar'} ${icon('arrow')}</button>${step>1?'<button class="btn btn-ghost mt8" type="button" data-action="register-back">Voltar uma etapa</button>':''}</form><p class="fine">Já tem uma conta? <a href="#/entrar">Entrar</a></p>`;}
function heading(title,sub,eyebrow='',action=''){return `<div class="app-heading"><div>${eyebrow?`<span class="eyebrow">${eyebrow}</span>`:''}<h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
const navItems=[['grid','Visão geral','/app'],['layers','Oportunidades','/app/oportunidades'],['wallet','Minha carteira','/app/carteira'],['bank','Conta digital','/app/conta-digital'],['swap','Marketplace','/app/marketplace'],['chart','Mesa OTC','/app/otc']];
function shell(body,title='Visão geral'){return `${demo()}<div class="app-layout"><button class="app-mobile-overlay" data-action="close-app-menu" aria-label="Fechar navegação"></button><aside class="sidebar" id="sidebar" aria-label="Navegação da plataforma">${logo(true)}<span class="label">Seu espaço</span><nav aria-label="Plataforma">${navItems.map(([i,t,h])=>`<a href="#${h}" class="nav-item ${route===h||(h==='/app/oportunidades'&&route.startsWith('/app/oferta/'))?'active':''}" ${route===h?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('')}<span class="label">Minha conta</span>${[['gift','Indicações','/app/indicacoes'],['doc','Informe de rendimentos','/app/informe'],['user','Meu perfil','/app/perfil']].map(([i,t,h])=>`<a class="nav-item ${route===h?'active':''}" href="#${h}" ${route===h?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="nav-item" href="#/faq">${icon('info')}Central de ajuda</a><a class="nav-item" href="#/">${icon('logout')}Voltar ao site</a><p class="sidebar-note">Uma nova forma de investir.</p></div></aside><div class="app-main"><header class="app-topbar"><button class="app-menu" aria-label="Abrir navegação da plataforma" aria-controls="sidebar" aria-expanded="false" data-action="app-menu">${icon('menu')}</button><div class="breadcrumbs"><span>Meu espaço</span><span>/</span><strong>${title}</strong></div><div class="row"><a href="#/oportunidades" class="btn btn-outline btn-sm">Ver site ${icon('arrow')}</a><a class="app-user" href="#/app/perfil"><span>Meu perfil</span><span class="avatar" aria-hidden="true">TH</span></a></div></header><main id="main" class="app-content" tabindex="-1">${body}${route==='/app/conta-digital'?'':`<p class="app-bottom-note">Valores de referência. Operações financeiras e abertura de conta ainda não estão disponíveis.</p>`}</main></div></div>`;}
function stat(label,value,foot,dark=false){return `<div class="stat ${dark?'dark':''}"><span class="stat-label">${label}</span><strong class="stat-value num money-value">${value}</strong><span class="stat-foot">${foot}</span></div>`;}
function investmentTable(){return `<div class="table-wrap"><table><caption class="sr-only">Posições de investimento</caption><thead><tr><th>Projeto</th><th>Capital aplicado</th><th>Prazo</th><th>Situação</th><th><span class="sr-only">Detalhes</span></th></tr></thead><tbody>${getWalletSnapshot().positions.filter(p=>p.principalCents>0).map(position=>{const o=offers.find(o=>o.id===position.projectId);if(!o)return '';const v=position.amount;return `<tr><td><span class="portfolio-art">${icon(o.art==='solar'?'sun':'building')}</span><strong>${o.name}</strong></td><td class="num money-value">${money(v)}</td><td>${o.term} meses</td><td>${badge('Ativo','green')}</td><td><a class="arrow-link" href="#/app/oferta/${o.id}">Ver projeto ${icon('chevron')}</a></td></tr>`;}).join('')}</tbody></table></div>`;}
function dashboard(){return shell(`${heading('Uma visão de tudo.','Acompanhe seus ativos e encontre seu próximo passo.','Bem-vindo ao seu espaço',arrow('Explorar oportunidades','#/app/oportunidades','btn btn-dark'))}<div class="stats">${stat('Capital aplicado',money(walletSummary().invested),'Posições em carteira',true)}${stat('Saldo disponível',money(walletSummary().available),'Equivalente em reais')}${stat('Rendimentos recebidos',money(walletSummary().income),'Créditos já incluídos no saldo')}</div>${renderDashboardInsights(getWalletSnapshot(),offers)}<div class="app-section-title"><h2>Seus projetos, de perto.</h2>${arrow('Minha carteira','#/app/carteira')}</div>${investmentTable()}<div class="app-section-title"><h2>Conheça novas possibilidades.</h2>${arrow('Ver todos','#/app/oportunidades')}</div><div class="offer-grid">${offers.slice(0,3).map(card).join('')}</div>`);}
function wallet(){return shell(`${heading('Minha carteira','Seu saldo, suas posições e seus próximos passos.','Organização para acompanhar')}<div class="stats">${balanceCard({id:'available',label:'Saldo disponível',value:walletSummary().available,foot:'Valores em reais',dark:true},icon)}${balanceCard({id:'applied',label:'Capital aplicado',value:walletSummary().invested,foot:'Seus investimentos'},icon)}${balanceCard({id:'earned',label:'Rendimentos recebidos',value:walletSummary().income,foot:'Créditos já incluídos no saldo'},icon)}</div><div class="quick-actions">${[['down','Depositar'],['up','Transferir'],['bank','Sacar'],['doc','Extrato'],['swap','Trocar'],['layers','Staking'],['globe','Bridge'],['gift','Recompensas']].map(([i,t])=>t==='Extrato'?`<a class="quick-action" href="#/app/extrato">${icon(i)}${t}</a>`:`<button class="quick-action" data-wallet-action="${t}">${icon(i)}${t}</button>`).join('')}</div>${balanceDetails(icon)}<div class="tabs" role="tablist" aria-label="Ativos da carteira">${['Investimentos','NFTs','Staking','Cobranças'].map((t,i)=>`<button class="tab ${state.walletTab===t?'active':''}" id="wallet-tab-${i}" role="tab" aria-controls="wallet-panel" aria-selected="${state.walletTab===t}" tabindex="${state.walletTab===t?0:-1}" data-wallet-tab="${t}">${t}</button>`).join('')}</div><section role="tabpanel" id="wallet-panel" aria-labelledby="wallet-tab-${['Investimentos','NFTs','Staking','Cobranças'].indexOf(state.walletTab)}">${state.walletTab==='Investimentos'?investmentTable():empty('Nenhum item nesta categoria',`A aba ${state.walletTab} organiza informações específicas. Você ainda não possui registros nesta categoria.`,'Conhecer oportunidades','go-offers')}</section>`,'Minha carteira');}
function extractRows(){const list=walletMovements().filter(t=>(state.extractFilter==='Todas'||t.type===state.extractFilter)&&t.name.toLowerCase().includes(state.extractQuery.toLowerCase()));return list.length?`<div class="table-wrap"><table><caption class="sr-only">Movimentações da carteira</caption><thead><tr><th>Data</th><th>Movimentação</th><th>Tipo</th><th>Valor</th><th>Status</th></tr></thead><tbody>${list.map(t=>`<tr><td>${t.date.split('-').reverse().join('/')}</td><td><strong>${esc(t.name)}</strong><span class="cell-sub">${esc(t.assetSymbol)} · ${number(Math.abs(t.assetAmount))} unidades</span></td><td>${t.type}</td><td class="num ${t.amount>0?'positive':'negative'}">${t.amount>0?'+':'−'} ${money(Math.abs(t.amount))}</td><td>${badge(t.status,'green')}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma movimentação encontrada','Tente outro tipo ou termo de busca.');}
function extract(){return shell(`${heading('Extrato','Tudo o que entrou e saiu, com contexto.','Minha carteira',`<button class="btn btn-dark btn-sm" data-action="export-extract">${icon('download')}Exportar CSV</button>`)}<div class="filters">${['Todas','Entrada','Saída'].map(t=>`<button class="chip ${state.extractFilter===t?'active':''}" aria-pressed="${state.extractFilter===t}" data-extract-filter="${t}">${t==='Todas'?'Todas as movimentações':t==='Entrada'?'Entradas':'Saídas'}</button>`).join('')}</div><div class="toolbar"><label class="search-wrap"><span class="sr-only">Buscar movimentação</span>${icon('search')}<input id="extract-search" type="search" placeholder="Buscar movimentação" value="${esc(state.extractQuery)}"></label>${badge('Dados fictícios')}</div><div id="extract-results" aria-live="polite">${extractRows()}</div>`,'Extrato');}
function bank(){return shell(`<h1 class="sr-only">Conta digital</h1>${renderBankJourney(state.bankStep,icon)}`,'Conta digital');}
function marketAssets(){return [{...upOpportunity,rate:Number(upOpportunity.rate.toFixed(2)),name:'Residencial UP',issuer:'Residencial UP · Sorocaba',art:'urban',risk:'Alto',progress:33,raised:247500,goal:750000,description:'Terreno de 1.564 m² no Lote 01 da Quadra B, em Sorocaba. O cenário de tokenização considera aquisição e revenda em 24 meses. Consulte as premissas e a apresentação completa do residencial.'},...offers].map(o=>({...o,unitPrice:100,available:100}));}
function marketCard(o){return `<article class="catalog-card"><div class="catalog-image"><a class="catalog-image-link" href="#/app/marketplace/${o.id}" aria-label="Ver ativo: ${o.name}">${o.id===upOpportunity.id?'<figure class="asset-photo"><img src="assets/photos/up/up-lote-01-viva.webp" alt="Terreno do Residencial UP em Sorocaba" loading="lazy" decoding="async"></figure>':photo(o.art,{sizes:'(max-width:760px) 100vw, 50vw'})}</a><span class="catalog-category">${o.category}</span><button class="catalog-save ${state.favorites.has(o.id)?'active':''}" data-favorite="${o.id}" aria-pressed="${state.favorites.has(o.id)}" aria-label="${state.favorites.has(o.id)?'Remover dos':'Adicionar aos'} favoritos: ${o.name}">${icon('heart')}</button></div><div class="catalog-copy"><div class="catalog-kicker"><span>Mercado secundário · ${o.category}</span></div><h3><a href="#/app/marketplace/${o.id}">${o.name}</a></h3><p class="catalog-description">${{reserva:'Desenvolvimento residencial. Conheça a estrutura e os direitos do ativo.',solar:'Geração de energia solar conectada à economia real.',agro:'Uma operação ligada à cadeia do agronegócio.',recebiveis:'Recebíveis empresariais e seus direitos contratuais.','up-sorocaba':'Um terreno de 1.564 m² no Residencial UP, em Sorocaba.'}[o.id]}</p><dl class="catalog-facts catalog-investment-facts"><div><dt>Rentabilidade do projeto</dt><dd>${number(o.rate)}<small>% a.a.</small></dd></div><div><dt>Preço por token</dt><dd><small>R$</small> ${number(o.unitPrice)}</dd></div><div><dt>Prazo do projeto</dt><dd>${o.term}<small> meses</small></dd></div><div><dt>Nível de risco</dt><dd>${o.risk}</dd></div></dl><p class="catalog-risk-note">Taxa do projeto; não representa retorno garantido na revenda.</p><div class="market-availability"><span>Quantidade de referência</span><strong>${o.available} tokens</strong></div><a class="catalog-link" href="#/app/marketplace/${o.id}"><span>Ver ativo</span><span class="catalog-link-arrow">${icon('arrow')}</span></a></div></article>`;}
function marketResults(){const query=(state.marketQuery||'').trim().toLocaleLowerCase('pt-BR');const list=marketAssets().filter(o=>(state.marketTab==='Todos'||o.category===state.marketTab)&&(!query||(o.name+' '+o.category+' '+o.issuer).toLocaleLowerCase('pt-BR').includes(query)));return `<p class="results-count mb24">${list.length} ${list.length===1?'ativo encontrado':'ativos encontrados'}</p>${list.length?`<div class="catalog-grid">${list.map(marketCard).join('')}</div>`:empty('Nenhum ativo encontrado','Tente outro nome ou categoria.','Limpar filtros','market-reset')}`;}
function marketplace(id){if(id){const o=marketAssets().find(o=>o.id===id);if(!o)return notFound();const tabs=['Visão geral','Documentos','Riscos','Atualizações'];let content=detailContent(o);if(o.id===upOpportunity.id){if(state.detailTab==='Visão geral')content=`<h3>Sobre o Residencial UP</h3><p>${o.description}</p><div class="mt20">${[['Área do terreno','1.564 m²'],['Localização','Lote 01 · Quadra B · Sorocaba'],['Cenário do projeto','Aquisição e revenda em 24 meses'],['Direitos e condições','Dependem da estrutura contratual']].map(([k,v])=>`<div class="summary-line"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><a class="btn btn-outline mt20" href="#/oferta/up-sorocaba">Conhecer o residencial completo ${icon('arrow')}</a>`;if(state.detailTab==='Documentos')content=`<h3>Informações do residencial</h3><p>Consulte a apresentação do terreno, as premissas do cenário e a fonte do anúncio.</p><a class="document-row" href="#/oferta/up-sorocaba"><span>Apresentação e premissas do Residencial UP</span>${icon('arrow')}</a><a class="document-row" href="https://a12corp.com.br/oportunidades/residencial-up-sorocaba" target="_blank" rel="noopener"><span>Anúncio de origem · A12</span>${icon('arrow')}</a>`;}
return shell(`<section class="market-detail"><div class="breadcrumbs"><a href="#/app/marketplace">← Marketplace</a><span>/</span><span>${o.name}</span></div><div class="app-heading"><div><span class="eyebrow">Mercado secundário · ${o.category}</span><h1>${o.name}</h1><p>Conheça o ativo e revise as condições antes de negociar.</p></div><button class="btn btn-outline btn-sm" data-favorite="${o.id}" aria-pressed="${state.favorites.has(o.id)}">${icon('heart')}${state.favorites.has(o.id)?'Salvo nos favoritos':'Salvar ativo'}</button></div><div class="detail-layout"><div class="market-detail-main"><div class="detail-art">${o.id===upOpportunity.id?'<figure class="asset-photo"><img src="assets/photos/up/up-lote-01-viva.webp" alt="Vista aérea do terreno do Residencial UP" decoding="async"></figure>':photo(o.art,{eager:true,sizes:'(max-width:900px) 100vw, 70vw'})}</div><div class="tabs" role="tablist" aria-label="Informações do ativo">${tabs.map((t,i)=>`<button id="detail-tab-${i}" class="tab ${state.detailTab===t?'active':''}" role="tab" aria-controls="detail-panel" aria-selected="${state.detailTab===t}" tabindex="${state.detailTab===t?0:-1}" data-detail-tab="${t}">${t}</button>`).join('')}</div><div class="panel" role="tabpanel" id="detail-panel" aria-labelledby="detail-tab-${tabs.indexOf(state.detailTab)}">${content}</div></div><aside class="detail-side panel market-order" aria-label="Condições da negociação"><span class="eyebrow">Preço por token</span><h2>${money(o.unitPrice)}</h2><p class="small">Valor de referência para revisão</p><dl class="market-detail-metrics">${[['Rentabilidade do projeto',number(o.rate),'% a.a.'],['Prazo do projeto',o.term,'meses'],['Quantidade de referência',o.available,'tokens'],['Nível de risco',o.risk,'']].map(([k,v,u])=>`<div><dt>${k}</dt><dd>${v}<small>${u}</small></dd></div>`).join('')}</dl><p class="footnote">A taxa do projeto não define o retorno de uma compra no mercado secundário. Preço, prazo restante e custos afetam o resultado.</p><form data-form="market-checkout"><input type="hidden" name="offer" value="${o.id}"><div class="field mt20"><label for="market-quantity">Quantos tokens quer revisar?</label><input id="market-quantity" data-market-asset="${o.id}" name="quantity" type="number" inputmode="numeric" min="1" max="${o.available}" step="1" value="${state.marketQuantities[o.id]||1}" required aria-describedby="market-quantity-hint"><small id="market-quantity-hint">De 1 a ${o.available} tokens.</small></div><div class="summary-line market-total"><span>Valor total</span><strong id="market-total">${money((state.marketQuantities[o.id]||1)*o.unitPrice)}</strong></div><div class="risk-note">Risco de perda do capital e baixa liquidez. A revisão não envia ordem nem transfere ativos.</div><label class="checkbox"><input type="checkbox" required><span>Entendi os riscos e que esta revisão não executa uma compra.</span></label><button class="btn btn-primary full mt20" type="submit">Revisar negociação ${icon('arrow')}</button></form></aside></div></section>`,'Marketplace');}
return shell(`<section class="market-catalog">${heading('Marketplace','Compare ativos e conheça as condições de negociação.','Mercado secundário')}<div class="market-intro"><p>Analise o projeto, o preço por token e os riscos. A liquidez depende das regras do ativo e da existência de compradores.</p></div><div class="market-toolbar"><label class="catalog-filter-field"><span>Buscar ativo</span><span class="catalog-search-input">${icon('search')}<input id="market-search" type="search" value="${esc(state.marketQuery||'')}" placeholder="Nome do ativo ou categoria"></span></label><div class="filters" role="group" aria-label="Categorias de ativos">${['Todos','Imobiliário','Energia','Agronegócio','Recebíveis'].map(t=>`<button class="chip ${state.marketTab===t?'active':''}" aria-pressed="${state.marketTab===t}" data-market-tab="${t}">${t}</button>`).join('')}</div></div><div id="market-results" aria-live="polite">${marketResults()}</div></section>`,'Marketplace');}
function otc(){return shell(renderOtc(icon),'Mesa OTC');}
function referrals(){return shell(`${heading('Conexões que ampliam possibilidades.','Convide alguém para conhecer a experiência TokenHub.','Indicações')}<div class="stats">${stat('Convites','0','Sem indicações reais',true)}${stat('Recompensas',money(0),'Programa comercial ainda não definido')}${stat('Situação','Demonstração','Sem promessa de remuneração')}</div><section class="referral-box"><span class="eyebrow">Uma boa conversa pode começar aqui</span><h2 style="font-size:32px">Compartilhe uma nova perspectiva.</h2><p class="mt20">Este link abre somente o cadastro de demonstração. Condições de um programa de indicação real dependem de definição comercial.</p><div class="referral-link"><label class="sr-only" for="referral-link">Link de demonstração</label><input id="referral-link" readonly value="${esc(location.origin+location.pathname+'#/cadastro?ref=demo')}"><button class="btn btn-dark" data-action="copy-referral">${icon('copy')}Copiar link</button></div></section><div class="app-section-title"><h2>Histórico de indicações</h2></div>${empty('Nenhuma indicação nesta demonstração','Os convites e eventos de um programa real apareceriam aqui.')}`,'Indicações');}
function profile(){return shell(`${heading('Meu perfil','Dados, documentos e segurança, com seus próprios espaços.','Minha conta')}<div class="profile-card"><span class="avatar">TH</span><div><h2>Usuário TokenHub</h2><p>Conta fictícia · Sem identidade ou credenciais reais</p></div></div><div class="tabs" role="tablist" aria-label="Área do perfil">${['Dados pessoais','Documentos','Segurança'].map((t,i)=>`<button id="profile-tab-${i}" class="tab ${state.profileTab===t?'active':''}" role="tab" aria-controls="profile-panel" aria-selected="${state.profileTab===t}" tabindex="${state.profileTab===t?0:-1}" data-profile-tab="${t}">${t}</button>`).join('')}</div><section class="panel" role="tabpanel" id="profile-panel" aria-labelledby="profile-tab-${['Dados pessoais','Documentos','Segurança'].indexOf(state.profileTab)}">${state.profileTab==='Dados pessoais'?`<form class="profile-form" data-form="profile"><div class="form-grid"><div class="field"><label for="profile-name">Nome completo</label><input id="profile-name" name="name" value="Usuário TokenHub" required minlength="3" maxlength="100"></div><div class="field"><label for="profile-user">Nome de usuário</label><input id="profile-user" name="username" value="usuario.tokenhub" required maxlength="30"></div><div class="field"><label for="profile-email">E-mail fictício</label><input id="profile-email" type="email" name="email" value="pessoa@example.com" required></div><div class="field"><label for="profile-phone">Telefone fictício</label><input id="profile-phone" name="phone" value="(11) 90000-0000" type="tel" minlength="10" maxlength="22"></div></div><div class="native-info">Alterações nesta versão ficam apenas na página e são descartadas ao sair.</div><button type="submit" class="btn btn-dark">Revisar alterações</button><div class="form-feedback" role="status"></div></form>`:state.profileTab==='Documentos'?`<h3>Verificação de identidade</h3><p>A versão operacional deve informar finalidade, retenção e responsável pelo tratamento dos documentos.</p><div class="notice mt20">${icon('shield')}<div><strong>Não envie documentos reais.</strong><p>Esta área demonstra a organização do cadastro, sem upload de arquivos.</p></div></div>${['Identificação pessoal','Comprovante cadastral','Validação de identidade'].map(t=>`<div class="document-row"><span>${t}</span>${badge('Sem envio','amber')}</div>`).join('')}`:`<h3>Configurações de segurança</h3>${[['Senha','A alteração depende de autenticação real e validação do titular.','Ver jornada'],['Autenticação em dois fatores','Exige um serviço de autenticação e verificação. Não está ativada nesta versão.','Conhecer 2FA'],['Sessões','Esta demonstração não possui sessões autenticadas em servidor.','Entender'],['Encerramento da conta','O encerramento real depende de obrigações, retenção e posições em aberto.','Ver informações']].map(([t,p,b])=>`<div class="security-row"><div><h3>${t}</h3><p>${p}</p></div><button class="btn btn-outline btn-sm" data-security="${t}">${b}</button></div>`).join('')}`}</section>`,'Meu perfil');}
function incomeReport(){return shell(`${heading('Informe de rendimentos','Uma visão organizada para consultar e imprimir.','Documentos',`<button class="btn btn-dark btn-sm" data-action="print">${icon('download')}Imprimir demonstrativo</button>`)}<div class="notice">${icon('info')}<div><strong>Documento demonstrativo, sem validade fiscal.</strong><p>A emissão real depende de dados tributários, titularidade, exercício e responsáveis pela operação.</p></div></div><article class="report-page">${logo()}<h2>Demonstrativo de posições</h2><span class="watermark">Sem validade fiscal</span><div class="cols mt32"><div><p>Titular fictício</p><strong>Usuário TokenHub</strong><p>Sem CPF ou identificação real</p></div><div><p>Período</p><strong>2026 · Dados ilustrativos</strong><p>Não corresponde a informe oficial</p></div></div><table><caption class="sr-only">Posições fictícias do demonstrativo</caption><thead><tr><th>Ativo ilustrativo</th><th>Capital aplicado</th><th>Valor recebido</th></tr></thead><tbody>${getWalletSnapshot().positions.map(p=>`<tr><td>${esc(offers.find(o=>o.id===p.projectId)?.name||p.projectId)}</td><td class="num">${money(p.amount)}</td><td class="num">${money(p.income)}</td></tr>`).join('')}<tr><td><strong>Total</strong></td><td class="num"><strong>${money(walletSummary().invested)}</strong></td><td class="num"><strong>${money(walletSummary().income)}</strong></td></tr></tbody></table><p>Este material foi criado exclusivamente para avaliar a apresentação de documentos na interface TokenHub. Não deve ser utilizado em declaração fiscal ou comprovação financeira.</p></article>`,'Informe de rendimentos');}
function empty(title,text,button='',action=''){return `<div class="empty">${icon('layers')}<h3>${title}</h3><p>${text}</p>${button?`<button class="btn btn-outline btn-sm" data-action="${action}">${button}</button>`:''}</div>`;}
function notFound(){return site(`${pageHero('Vamos encontrar o caminho','Página não encontrada.','O endereço pode ter mudado. Você pode voltar ao início ou explorar as oportunidades.')}<section class="section"><div class="container row wrap">${arrow('Ir para o início','#/','btn btn-dark')}${arrow('Ver oportunidades','#/oportunidades','btn btn-outline')}</div></section>`);}

function render(){disposeMotion();disposeOtc();route=(location.hash.slice(1)||'/').split('?')[0].replace(/\/$/,'')||'/';if(route!=='/app/conta-digital'){clearBankDraft();state.bankStep=0;}let html;const parts=route.split('/').filter(Boolean);if(route==='/')html=home();else if(route==='/oportunidades')html=opportunities();else if(parts[0]==='oferta')html=offerDetail(parts[1]);else if(parts[0]==='ecossistema'){const content=serviceContent(parts[1],icon);html=content?site(content):notFound();}else if(route==='/como-funciona')html=how();else if(route==='/quem-somos')html=about();else if(route==='/para-empresas')html=companies();else if(route==='/contato')html=contact();else if(route==='/faq')html=faqPage();else if(parts[0]==='conteudos')html=contentPage(parts[1]);else if(route==='/material-didatico')html=legal('material');else if(parts[0]==='legal')html=legal(parts[1]);else if(route==='/sobre-prototipo')html=prototypeInfo();else if(route==='/entrar')html=auth();else if(route==='/cadastro')html=auth('register');else if(route==='/recuperar-senha')html=auth('forgot');else if(route==='/app')html=dashboard();else if(route==='/app/oportunidades')html=opportunities(true);else if(parts[0]==='app'&&parts[1]==='oferta')html=offerDetail(parts[2],true);else if(route==='/app/carteira')html=wallet();else if(route==='/app/extrato')html=extract();else if(route==='/app/conta-digital')html=bank();else if(parts[0]==='app'&&parts[1]==='marketplace')html=marketplace(parts[2]);else if(route==='/app/otc')html=otc();else if(route==='/app/indicacoes')html=referrals();else if(route==='/app/perfil')html=profile();else if(route==='/app/informe')html=incomeReport();else html=notFound();app.innerHTML=html;const dashboardMotion=mountDashboardMotion(app);const walletBalances=mountWalletBalances(app);const accountJourney=mountBankJourney(app);const baseMotion=mountMotion(app),aboutMotion=mountAboutMotion(app);const vfxMotion=mountVfx(app);const businessMotion=mountCompanies(app),upConditions=mountUpConditions(app);disposeMotion=()=>{dashboardMotion();walletBalances();accountJourney();upConditions();businessMotion();vfxMotion();baseMotion();aboutMotion();};disposeOtc=mountOtc(app,icon);const h=app.querySelector('h1');document.title=(h?h.textContent.trim():'Meu espaço')+' | TokenHub';}
function refreshMain(){const scroll=window.scrollY;const id=document.activeElement?.id;render();window.scrollTo(0,scroll);if(id)document.getElementById(id)?.focus({preventScroll:true});}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function openDialog(title,body){const d=document.querySelector('#dialog');if(!d.open)lastDialogFocus=document.activeElement;d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="Fechar janela">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;d.showModal();}
function closeDialog(){document.querySelector('#dialog').close();lastDialogFocus?.focus?.();}
function updateOfferResults(){document.querySelector('#offers-results').innerHTML=offerResults();app.dispatchEvent(new Event('offers:updated'));}
function setChips(key,value,selector){state[key]=value;document.querySelectorAll(selector).forEach(b=>{const current=b.textContent.trim();const active=key==='filter'?(b.dataset.category===value):key==='faqCategory'?(b.dataset.faqCategory===value):(b.dataset.extractFilter===value);b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function invest(id){const o=offers.find(o=>o.id===id);if(!o)return;openDialog('Simular aplicação',`<p>Explore as condições de ${o.name}. Nenhum recurso será movimentado.</p><form data-form="invest"><input type="hidden" name="offer" value="${o.id}"><div class="field"><label for="invest-amount">Valor ilustrativo (R$)</label><input id="invest-amount" name="amount" type="number" min="${o.min}" max="1000000" value="${o.min}" step="1" required><small class="hint">Valor mínimo: ${money(o.min)}</small></div><div class="summary-line"><span>Prazo</span><strong>${o.term} meses</strong></div><div class="risk-note">O retorno apresentado é hipotético. O capital pode ser perdido e não há garantia de liquidez.</div><label class="checkbox"><input type="checkbox" required><span>Li as condições demonstrativas e entendo os riscos apresentados.</span></label><button type="submit" class="btn btn-primary">Revisar cenário ${icon('arrow')}</button></form>`);}
function walletAction(action){if(action==='Trocar'){location.hash='/app/otc';return;}if(action==='Recompensas'){location.hash='/app/indicacoes';return;}if(['Staking','Bridge'].includes(action)){openDialog(action,`<p>${action==='Staking'?'A jornada real precisa apresentar protocolo, prazo de bloqueio, custos, riscos, regras de remuneração e resgate.':'A jornada real precisa apresentar rede de origem, rede de destino, ativo, endereço, taxas e riscos de transferência.'}</p><div class="native-info">Esta demonstração não conecta carteiras, assina mensagens nem executa operações em blockchain.</div><button class="btn btn-dark" data-action="close-dialog">Entendi</button>`);return;}openDialog(action+' · Demonstração',`<p>Esta jornada utiliza valores fictícios e não cria movimentações reais.</p><form data-form="wallet-operation"><input type="hidden" name="action" value="${action}"><div class="field"><label for="operation-amount">Valor ilustrativo (R$)</label><input id="operation-amount" name="amount" type="number" min="1" max="${action==='Depositar'?100000:action==='Sacar'?withdrawalLimit():walletSummary().available}" value="100" required></div>${action!=='Depositar'?'<div class="field"><label for="operation-destination">Destino fictício</label><input id="operation-destination" name="destination" required placeholder="Use apenas um identificador fictício" maxlength="80"></div>':''}<div class="native-info">Não há QR Code de pagamento, endereço de carteira, chave Pix ou conta bancária real.</div><button type="submit" class="btn btn-dark">Revisar demonstração ${icon('arrow')}</button></form>`);}

document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-action]');if(!b)return;const action=b.dataset.action;
 if(b.dataset.favorite){const id=b.dataset.favorite;if(![upOpportunity,...offers].some(o=>o.id===id))return;state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);try{localStorage.setItem('tokenhub:favorites',JSON.stringify([...state.favorites]));}catch{}if(document.querySelector('#offers-results'))updateOfferResults();else refreshMain();toast(state.favorites.has(id)?'Projeto salvo nos favoritos.':'Projeto removido dos favoritos.');}
 if(b.dataset.upPhoto!==undefined)openUpGallery(document.querySelector('#dialog'),Number(b.dataset.upPhoto));
 if(b.dataset.category){setChips('filter',b.dataset.category,'[data-category]');updateOfferResults();}
 if(b.dataset.faqCategory){setChips('faqCategory',b.dataset.faqCategory,'[data-faq-category]');document.querySelector('#faq-results').innerHTML=faqResults();}
 if(b.dataset.extractFilter){setChips('extractFilter',b.dataset.extractFilter,'[data-extract-filter]');document.querySelector('#extract-results').innerHTML=extractRows();}
 if(b.dataset.detailTab){state.detailTab=b.dataset.detailTab;const id=b.id;refreshMain();document.getElementById(id)?.focus();}
 if(b.dataset.walletTab){state.walletTab=b.dataset.walletTab;const id=b.id;refreshMain();document.getElementById(id)?.focus();}
 if(b.dataset.profileTab){state.profileTab=b.dataset.profileTab;const id=b.id;refreshMain();document.getElementById(id)?.focus();}
 if(b.dataset.marketTab){state.marketTab=b.dataset.marketTab;refreshMain();}
 if(b.dataset.invest)invest(b.dataset.invest);
 if(b.dataset.walletAction)walletAction(b.dataset.walletAction);
 if(b.dataset.balanceToggle){const values={available:[walletSummary().available,'Saldo disponível'],applied:[walletSummary().invested,'Capital aplicado'],earned:[walletSummary().income,'Rendimentos recebidos']};const row=values[b.dataset.balanceToggle];if(row)toggleBalance(b.dataset.balanceToggle,row[0],row[1],b);}
 if(b.dataset.assetToggle)toggleAsset(b.dataset.assetToggle,b);
 if(b.dataset.assetCopy)toast(await copyAssetIdentifier(b.dataset.assetCopy)?'Identificador de demonstração copiado. Não é um endereço de depósito.':'A cópia não está disponível neste navegador.');
 if(b.dataset.bankingAction)openDialog(b.dataset.bankingAction+' · Proposta',`<p>Esta área demonstra o acesso ao serviço. Nenhum pagamento, transferência, cobrança ou chave Pix é criado.</p><div class="native-info">A operação real depende de parceiro bancário, verificação de identidade, limites e confirmação autenticada.</div><button class="btn btn-dark" data-action="close-dialog">Voltar à conta</button>`);
 if(b.dataset.security)openDialog(b.dataset.security,`<p>Esta é uma proposta da jornada de segurança. Nenhuma configuração da sua conta real é alterada.</p><div class="native-info">${b.dataset.security==='Autenticação em dois fatores'?'Na versão operacional: solicitar confirmação de identidade, apresentar método de cadastro e validar o código antes da ativação.':'A versão operacional precisa validar o titular e informar as consequências antes de qualquer alteração.'}</div><button class="btn btn-dark" data-action="close-dialog">Entendi</button>`);
 if(b.dataset.document){const [id,index]=b.dataset.document.split(':');const o=offers.find(o=>o.id===id);const title=['Informações essenciais','Condições da oferta','Matriz de riscos'][Number(index)];if(o&&title)download('TokenHub-modelo-'+id+'-'+index+'.txt',`TOKENHUB — MODELO DEMONSTRATIVO\n${title}\nProjeto fictício: ${o.name}\n\nEste arquivo demonstra a organização da documentação e não possui validade contratual.\nNenhuma oferta real é descrita aqui.\nCondições, direitos, riscos, custos e responsáveis deverão constar de documentação validada.\n`);}
 if(b.dataset.password){const input=document.getElementById(b.dataset.password);const show=input.type==='password';input.type=show?'text':'password';b.setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha');b.setAttribute('aria-pressed',String(show));}
 if(action==='site-menu'){const n=document.querySelector('#site-nav');const open=n.classList.toggle('open');b.setAttribute('aria-expanded',String(open));}
 if(action==='app-menu'){document.querySelector('#sidebar').classList.add('open');document.querySelector('.app-mobile-overlay').classList.add('open');b.setAttribute('aria-expanded','true');document.querySelector('#sidebar a').focus();}
 if(action==='close-app-menu')closeAppMenu();
 if(action==='close-dialog')closeDialog();
 if(action==='only-favorites'){state.onlyFavorites=!state.onlyFavorites;b.setAttribute('aria-pressed',String(state.onlyFavorites));b.innerHTML=icon('heart')+(route==='/oportunidades'?'Somente favoritos':state.onlyFavorites?'Todos os projetos':'Favoritos');updateOfferResults();}
 if(action==='reset-filters'){state.filter='Todas';state.query='';state.onlyFavorites=false;state.sort='default';refreshMain();}
 if(action==='toggle-balances'){state.hidden=!state.hidden;refreshMain();}
 if(action==='register-back'){state.registrationStep=Math.max(1,state.registrationStep-1);refreshMain();document.querySelector('h1')?.focus();}
 if(action==='market-reset'){state.marketTab='Todos';state.marketQuery='';refreshMain();}
 if(action==='bank-start'){state.bankStep=1;refreshMain();document.querySelector('#tj-title')?.focus();}
 if(action==='bank-next'){if(!validateBankStep())return;if(state.bankStep===3)clearBankDraft();state.bankStep=Math.min(4,state.bankStep+1);refreshMain();document.querySelector('#tj-title')?.focus();}
 if(action==='bank-back'){state.bankStep=Math.max(0,state.bankStep-1);refreshMain();document.querySelector('#tj-title')?.focus();}
 if(action==='bank-edit-contact'){state.bankStep=1;refreshMain();document.querySelector('#tj-title')?.focus();}
 if(action==='bank-restart'){clearBankDraft();state.bankStep=0;refreshMain();document.querySelector('#tj-title')?.focus();}
 if(action==='more-assets'){toggleOtherAssets();refreshMain();document.querySelector('[data-action="more-assets"]')?.focus();}
 if(action==='go-offers')location.hash='/app/oportunidades';
 if(action==='print')window.print();
 if(action==='clear-demo'){state.favorites.clear();try{localStorage.removeItem('tokenhub:favorites');}catch{}toast('Favoritos apagados deste navegador.');}
 if(action==='copy-referral'){const input=document.getElementById('referral-link');try{await navigator.clipboard.writeText(input.value);toast('Link da demonstração copiado.');}catch{input.focus();input.select();toast('Selecione e copie o link com Ctrl+C.');}}
 if(action==='export-extract'){const lines=[['Data','Movimentação','Tipo','Valor BRL','Status'],...walletMovements().map(t=>[t.date,t.name,t.type,String(t.amount).replace('.',','),t.status])];download('TokenHub-extrato-demonstrativo.csv','\uFEFF'+lines.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Extrato fictício exportado.');}
});
function closeAppMenu(){document.querySelector('#sidebar')?.classList.remove('open');document.querySelector('.app-mobile-overlay')?.classList.remove('open');const b=document.querySelector('[data-action="app-menu"]');b?.setAttribute('aria-expanded','false');b?.focus();}
document.addEventListener('input',e=>{const el=e.target;if(el.id==='market-search'){state.marketQuery=el.value;document.querySelector('#market-results').innerHTML=marketResults();app.dispatchEvent(new Event('offers:updated'));}if(el.id==='offer-search'){state.query=el.value;updateOfferResults();}if(el.id==='faq-search'){state.faqQuery=el.value;document.querySelector('#faq-results').innerHTML=faqResults();}if(el.id==='extract-search'){state.extractQuery=el.value;document.querySelector('#extract-results').innerHTML=extractRows();}if(el.id.startsWith('calc-'))updateCalculator(el);if(el.id==='market-quantity'){if(el.validity.valid)state.marketQuantities[el.dataset.marketAsset]=Number(el.value);document.querySelector('#market-total').textContent=el.validity.valid?money(Number(el.value)*100):'Quantidade inválida';}});
document.addEventListener('change',e=>{if(e.target.id==='offer-sort'){state.sort=e.target.value;updateOfferResults();}if(e.target.id==='calc-term')updateCalculator();});
function updateCalculator(source){updateSimulator(source);}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#sidebar.open'))closeAppMenu();const t=e.target.closest('[role="tab"]');if(t&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...t.parentElement.querySelectorAll('[role="tab"]')];const i=tabs.indexOf(t);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();}if(document.querySelector('#sidebar.open')&&e.key==='Tab'){const controls=[...document.querySelectorAll('#sidebar a,#sidebar button')];const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.querySelector('#dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
document.querySelector('#dialog').addEventListener('close',()=>lastDialogFocus?.focus?.());
document.addEventListener('submit',e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form),type=form.dataset.form;
 if(type==='login'){form.reset();location.hash='/app';toast('Você está na demonstração. Nenhum login real foi realizado.');}
 if(type==='forgot'){form.reset();form.querySelector('.form-feedback').innerHTML='<div class="form-success mt20">Em uma plataforma operacional, as orientações seriam enviadas se o endereço estivesse cadastrado. Nenhum e-mail foi enviado nesta demonstração.</div>';}
 if(type==='register'){if(state.registrationStep===2&&data.get('password')!==data.get('confirmation')){document.querySelector('#registration-error').innerHTML='<div class="form-error">As senhas de demonstração precisam ser iguais.</div>';document.querySelector('#reg-confirm').focus();return;}form.reset();state.registrationStep++;render();window.scrollTo(0,0);document.querySelector('#main')?.focus({preventScroll:true});}
 if(type==='company'||type==='contact'){form.reset();form.querySelector('.form-feedback').innerHTML='<div class="form-success mt20"><strong>Jornada demonstrada.</strong> A mensagem foi validada apenas no navegador. Nenhum contato foi enviado ou salvo.</div>';}
 if(type==='profile'){form.querySelector('.form-feedback').innerHTML='<div class="form-success mt20">Alterações demonstradas. Nenhum dado foi enviado ou salvo em servidor. Os valores serão descartados ao sair desta tela.</div>';}
 if(type==='invest'){const o=offers.find(o=>o.id===data.get('offer')),amount=Number(data.get('amount'));if(!o||!Number.isFinite(amount)||amount<o.min||amount>1000000)return;openDialog('Seu cenário, revisado.',`<p>Aplicação hipotética em ${o.name}.</p><div class="summary-line"><span>Capital ilustrativo</span><strong>${money(amount)}</strong></div><div class="summary-line"><span>Prazo</span><strong>${o.term} meses</strong></div><div class="summary-line"><span>Valor bruto hipotético</span><strong>${money(amount*Math.pow(1+o.rate/100,o.term/12))}</strong></div><div class="risk-note">Cálculo com taxa constante, sem impostos ou custos. Não representa retorno garantido.</div><p class="small">Demonstração concluída. Não houve aplicação, reserva ou movimentação na carteira.</p><button class="btn btn-dark" data-action="close-dialog">Concluir revisão</button>`);}
 if(type==='wallet-operation'){const amount=Number(data.get('amount')),action=data.get('action');if(!Number.isFinite(amount)||amount<=0||(action!=='Depositar'&&amount>(action==='Sacar'?withdrawalLimit():walletSummary().available)))return;form.reset();openDialog('Revisão da demonstração',`<p>${action} · ${money(amount)}</p><div class="native-info">Destino e valores foram usados somente nesta visualização. Nenhuma ordem foi enviada e o saldo permanece igual.</div><button class="btn btn-dark" data-action="close-dialog">Concluir sem movimentar</button>`);}
 if(type==='otc'){const qty=Number(data.get('quantity'));if(!Number.isFinite(qty)||qty<20||qty>100000)return;document.querySelector('#otc-result').innerHTML=`<span class="eyebrow">02 · Cenário ilustrativo</span><h3>Revise cada condição.</h3><div class="mt20">${[['Quantidade',number(qty)+' USDT fictícios'],['Taxa de conversão hipotética','R$ 5,00 por unidade'],['Valor bruto do cenário',money(qty*5)],['Custo hipotético (1%)',money(qty*5*.01)],['Valor após o custo hipotético',money(qty*5*.99)]].map(([k,v])=>`<div class="summary-line"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="risk-note">Valores estáticos e fictícios. Nenhum preço foi consultado ou travado. Nenhuma operação pode ser executada nesta versão.</div>`;}
 if(type==='market-checkout'){const qty=Number(data.get('quantity')),o=marketAssets().find(o=>o.id===data.get('offer'));if(!o||!Number.isInteger(qty)||qty<1||qty>100)return;openDialog('Revisão da negociação',`<p>${o.name} · ${qty} ${qty===1?'unidade':'unidades'} nesta simulação.</p><div class="summary-line"><span>Valor total</span><strong>${money(qty*100)}</strong></div><div class="native-info">Demonstração concluída. Nenhuma ordem foi enviada, nenhum valor foi debitado e nenhum ativo foi transferido.</div><button class="btn btn-dark" data-action="close-dialog">Concluir revisão</button>`);}
});
window.addEventListener('hashchange',()=>{const navigate=()=>{state.detailTab='Visão geral';render();window.scrollTo(0,0);document.querySelector('#main')?.focus({preventScroll:true});};if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches)document.startViewTransition(navigate);else navigate();});
render();






